/**
 * The journal.
 *
 * Twenty articles written for the questions people actually type into Google
 * before they book treatment abroad — what it costs, whether the clinic is
 * real, which technique, how long in Istanbul, and what happens if it goes
 * wrong once they are home again.
 *
 * Each one ends by linking to the treatment pages it concerns. That is the
 * architecture: the article catches the search, the treatment page converts it.
 *
 * Generated. Edit the articles in the admin like any other post — the installer
 * writes them out as ordinary content and never reads this back.
 *
 * @package VeaHealth
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

