	return array(
		'Costs and money'              => __( 'What treatment abroad actually costs, itemised, and where the saving comes from.', 'veahealth' ),
		'Safety and choosing a clinic' => __( 'How to check a clinic before you send a deposit, and what to do if something goes wrong.', 'veahealth' ),
		'Choosing a treatment'         => __( 'The comparisons people make before deciding, answered without a sales pitch.', 'veahealth' ),
		'Planning your trip'           => __( 'Dates, flights, packing and Istanbul itself, from a patient\'s point of view.', 'veahealth' ),
